window.docContents[112].resolve({"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Reduction":{"contents":"Likewise the definitions of IsValue and Step.\n\ninductive Tm.IsValue : Tm → Prop where\n  | abs : ∀ x τ₂ t₁,\n      IsValue <{λ ~x : ~τ₂ . ~t₁}>\n  | tru :\n      IsValue <{true}>\n  | fls :\n      IsValue <{false}>\n  | unit :\n      IsValue .unit\n\n-- Fill in more rules when you do the `products` exercise later\n  | pair : ∀ v₁ v₂,\n      IsValue v₁ →\n      IsValue v₂ →\n      IsValue <{(~v₁, ~v₂)}>\n\nattribute [StlcSubEval] Tm.IsValue.pair\n\nattribute [StlcSubEval] Tm.IsValue.abs Tm.IsValue.tru Tm.IsValue.fls Tm.IsValue.unit\n\n\nsection\nset_option hygiene false in\nlocal notation:40 t:41 \" ⟶ \" t':41 => Step t t'\n\ninductive Step : Tm → Tm → Prop where\n  -- pure STLC\n  | appAbs (x : String) (τ₂ : Ty) (t₁ v₂ : Tm) :\n        v₂.IsValue →\n         <{(λ ~x: ~τ₂ . ~t₁) ~v₂}> ⟶ <{ [~x := ~v₂] ~t₁ }>\n  | app₁ (t₁ t₁' t₂ : Tm) :\n         t₁ ⟶ t₁' →\n         <{~t₁ ~t₂}> ⟶ <{~t₁' ~t₂}>\n  | app₂ (v₁ t₂ t₂' : Tm) :\n        v₁.IsValue →\n         t₂ ⟶ t₂' →\n         <{~v₁ ~t₂}> ⟶ <{~v₁  ~t₂'}>\n  -- booleans\n  | ifStep (t₁ t₁' t₂ t₃ : Tm) (h : t₁ ⟶ t₁') :\n      <{ if ~t₁ then ~t₂ else ~t₃ }> ⟶ <{ if ~t₁' then ~t₂ else ~t₃ }>\n  | ifTrue (t₂ t₃ : Tm) :\n      <{ if true then ~t₂ else ~t₃ }> ⟶ t₂\n  | ifFalse (t₂ t₃ : Tm) :\n      <{ if false then ~t₂ else ~t₃ }> ⟶ t₃\n\n  -- Fill in more rules when you do the `products` exercise later\n  | pair₁  (t₁ t₁' t₂ : Tm) :\n        t₁ ⟶ t₁' →\n        <{ (~t₁, ~t₂) }> ⟶ <{ (~t₁' , ~t₂) }>\n  | pair₂ (v₁ t₂ t₂' : Tm) :\n        v₁.IsValue →\n        t₂ ⟶ t₂' →\n        <{ (~v₁, ~t₂) }> ⟶  <{ (~v₁, ~t₂') }>\n  | fst₁ (t t' : Tm) :\n        t ⟶ t' →\n        <{ fst ~t }> ⟶ <{ fst ~t' }>\n  | fstPair (v₁ v₂ : Tm) :\n        v₁.IsValue →\n        v₂.IsValue →\n        Tm.fst  <{ (~v₁ , ~v₂) }> ⟶ v₁\n  | snd₁ (t t' : Tm) :\n        t ⟶ t' →\n        <{ snd ~t }> ⟶ <{ snd ~t' }>\n  | sndPair (v₁ v₂ : Tm) :\n        v₁.IsValue →\n        v₂.IsValue →\n        Tm.snd  <{ (~v₁, ~v₂) }> ⟶ v₂\nend\n\nscoped notation:40 t:41 \" ⟶ \" t':41 => Step t t'\nscoped notation:40 t:41 \" ⟶* \" t':41 => Multi Step t t'\n\n-- Be sure to add your constructors for pairs to this list later\nattribute [StlcSubEval] Step.appAbs Step.app₁ Step.app₂\n    Step.ifStep Step.ifTrue Step.ifFalse\n    Step.pair₁ Step.pair₂ Step.fst₁ Step.fstPair\n    Step.snd₁ Step.sndPair\n\n\n","context":"Type Systems\u0009Sub: Subtyping\u0009Formal Definitions","header":"8.2.3. Reduction","id":"/Sub/#Type-Systems--Sub___-Subtyping--Formal-Definitions--Reduction"}});